(167257, 9536, 4077, '<td valign="top">One of the better abstracts in this challenge.</td>', 'One of the better abstracts in this challenge.', '2002-12-09 07:18:30.000000', NULL, 1),
(167258, 9461, 4615, '<td valign="top">undersize photo...interesting.  Looks a little crowded, or "squashed".  Some more room would benefit it.</td>', 'undersize photo...interesting.  Looks a little crowded, or "squashed".  Some more room would benefit it.', '2002-12-09 07:19:48.000000', NULL, 1),
(167260, 9446, 4077, '<td valign="top">Good concept, excellent execution. The way the \''fixed\'' figure provides a static point of reference is perfect.</td>', 'Good concept, excellent execution. The way the \''fixed\'' figure provides a static point of reference is perfect.', '2002-12-09 07:21:10.000000', NULL, 1),
