(167418, 9533, 4049, '<td valign="top">Cute</td>', 'Cute', '2002-12-09 09:47:22.000000', NULL, 1),
(167429, 9516, 4049, '<td valign="top">I think it is reprehensible that anyone would consider bringing a child into this world. If you truly loved your unborn child you would spare it the life of suffering, depression and misery it will undoubtedly have in this cruel oppressive world. Humans should allow our race to die out since we have only grown more cold, heartless and selfish as we progress. There should be manditory sterilizations. We must think beyond our own selfish desires to propigate our species and our fear of death! Love your children enough not to even conceive them!</td>', 'I think it is reprehensible that anyone would consider bringing a child into this world. If you truly loved your unborn child you would spare it the life of suffering, depression and misery it will undoubtedly have in this cruel oppressive world. Humans should allow our race to die out since we have only grown more cold, heartless and selfish as we progress. There should be manditory sterilizations. We must think beyond our own selfish desires to propigate our species and our fear of death! Love your children enough not to even conceive them!', '2002-12-09 09:53:41.000000', NULL, 1),
(167431, 9520, 3859, '<td valign="top">This is wonderful.  The sleeves of her shirt in motion give her a winged appearance. I love the pose.  With her head down, I feel the emphasis is on the motion and not her face.  The red shirt is perfect.  A definite 10.</td>', 'This is wonderful.  The sleeves of her shirt in motion give her a winged appearance. I love the pose.  With her head down, I feel the emphasis is on the motion and not her face.  The red shirt is perfect.  A definite 10.', '2002-12-09 09:54:34.000000', NULL, 1),
(167432, 9455, 3859, '<td valign="top">This is very nice.  Great composition. The red adds the perfect amount of color to the shot.  Wonderful wing action.</td>', 'This is very nice.  Great composition. The red adds the perfect amount of color to the shot.  Wonderful wing action.', '2002-12-09 09:58:05.000000', NULL, 1),
(167435, 9332, 4049, '<td valign="top">She looks absolutely thrilled.</td>', 'She looks absolutely thrilled.', '2002-12-09 09:59:19.000000', NULL, 1),
