INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(168965, 9516, 4275, '<td valign="top">lovely name im going to call my baby girl that when i have one cool pix 10</td>', 'lovely name im going to call my baby girl that when i have one cool pix 10', '2002-12-10 02:13:29.000000', NULL, 1),
(168966, 9311, 4210, '<td valign="top">I think it''s awesome how the reflection appears still, and the other stuff is blurred.</td>', 'I think it''s awesome how the reflection appears still, and the other stuff is blurred.', '2002-12-10 02:15:21.000000', NULL, 1),
(168968, 9280, 1031, '<td valign="top">Personally I''d probably like this better if you''d been able to get a clear shot without the people in the foreground.</td>', 'Personally I''d probably like this better if you''d been able to get a clear shot without the people in the foreground.', '2002-12-10 02:21:23.000000', NULL, 1),
(168970, 9353, 1031, '<td valign="top">Nice timing. I''ve used these tubular slides as props myself (see my entry for "Upside Down" if you''re curious).</td>', 'Nice timing. I''ve used these tubular slides as props myself (see my entry for "Upside Down" if you''re curious).', '2002-12-10 02:24:01.000000', NULL, 1),
(168971, 9341, 4210, '<td valign="top">I don''t really like the boarder. If you really wanted one, smaller might have been the way to go.</td>', 'I don''t really like the boarder. If you really wanted one, smaller might have been the way to go.', '2002-12-10 02:25:55.000000', NULL, 1),
(168987, 9344, 4186, '<td valign="top">great combination of stillness and motion blur. composition is interesting, especially with the non-standard ratio. the subject makes good use of the different size, fills the frame nicely. i like the slightly over-exposed white of the background alot, and the orange the sun makes. the colors are great, using near compliments (green oiffset with a little orange) quite nicely. i think it deserves a ten.</td>', 'great combination of stillness and motion blur. composition is interesting, especially with the non-standard ratio. the subject makes good use of the different size, fills the frame nicely. i like the slightly over-exposed white of the background alot, and the orange the sun makes. the colors are great, using near compliments (green oiffset with a little orange) quite nicely. i think it deserves a ten.', '2002-12-10 02:37:44.000000', NULL, 1),
(168991, 9474, 4186, '<td valign="top">the black and white (IR?) was a good choice. people are gonna lecture you about the rule of thirds, but the central composition really makes this piece. the idea of the waterfall was not very creative, but the execution is marvelously done. 9</td>', 'the black and white (IR?) was a good choice. people are gonna lecture you about the rule of thirds, but the central composition really makes this piece. the idea of the waterfall was not very creative, but the execution is marvelously done. 9', '2002-12-10 02:44:02.000000', NULL, 1),
(168995, 9261, 4186, '<td valign="top">another obvious concept, amazingly executed. the slight grain adds to the flow. the division of the colors (grey in the bottom quarter, white in the top, color in the other two) works, and the colors themselves work very well. the way the white stripe in the center flows is amazing. the focus of the "end" of the road being off center was a good choice, and it really draws your eye into the weaving motion of the road. 9</td>', 'another obvious concept, amazingly executed. the slight grain adds to the flow. the division of the colors (grey in the bottom quarter, white in the top, color in the other two) works, and the colors themselves work very well. the way the white stripe in the center flows is amazing. the focus of the "end" of the road being off center was a good choice, and it really draws your eye into the weaving motion of the road. 9', '2002-12-10 02:47:52.000000', NULL, 1),
(169000, 9435, 4186, '<td valign="top">obvious concept, amazing execution. colors are great (greens and oranges being near-compliments) and the blur is not excessive, and captures the motion well. also, the perspective, and the point you choice for the point of perspective (the angle you shot at) makes one''s eyes follow the lines of the floor, windows, ceiling, etc, from one end of the picture to the other, which aids the idea of motion greatly. overall, a fantastic picture. 9</td>', 'obvious concept, amazing execution. colors are great (greens and oranges being near-compliments) and the blur is not excessive, and captures the motion well. also, the perspective, and the point you choice for the point of perspective (the angle you shot at) makes one''s eyes follow the lines of the floor, windows, ceiling, etc, from one end of the picture to the other, which aids the idea of motion greatly. overall, a fantastic picture. 9', '2002-12-10 02:54:47.000000', NULL, 1),
(169001, 9466, 4455, '<td valign="top">mmmm,i really love it-anz</td>', 'mmmm,i really love it-anz', '2002-12-10 03:27:05.000000', NULL, 1),
(169002, 9498, 4455, '<td valign="top">lovely use of colours ,great work-anz</td>', 'lovely use of colours ,great work-anz', '2002-12-10 03:28:08.000000', NULL, 1),
(169003, 9444, 4455, '<td valign="top">wow it looks like a metalic river-i really like it well done-anz</td>', 'wow it looks like a metalic river-i really like it well done-anz', '2002-12-10 03:30:58.000000', NULL, 1),
(169005, 9269, 4455, '<td valign="top">beautiful-anz</td>', 'beautiful-anz', '2002-12-10 03:55:45.000000', NULL, 1),
