(169017, 9529, 5158, '<td valign="top">Well done! Could be for a fragrance commercial. Very mystic. 8 from me</td>', 'Well done! Could be for a fragrance commercial. Very mystic. 8 from me', '2002-12-10 05:02:35.000000', NULL, 1),
