(169874, 9560, 1143, '<td valign="top">This is great, but if you could somehow create the motion blur just in the bg and have him in focus then it would be awesome. Sort of like the look you get when you sit in the center of a merry go round and take a pic of someone on the edge of it while it spins. Not sure that''s at all possible of course.  ;oP  I just wanna see this kid!</td>', 'This is great, but if you could somehow create the motion blur just in the bg and have him in focus then it would be awesome. Sort of like the look you get when you sit in the center of a merry go round and take a pic of someone on the edge of it while it spins. Not sure that''s at all possible of course.  ;oP  I just wanna see this kid!', '2002-12-11 00:49:38.000000', NULL, 1),
(169875, 9261, 2752, '<td valign="top">makes for a very good abstract..well composed and good colors.</td>', 'makes for a very good abstract..well composed and good colors.', '2002-12-11 00:49:55.000000', NULL, 1),
(169876, 9478, 2752, '<td valign="top">very clever and well done shot</td>', 'very clever and well done shot', '2002-12-11 00:51:04.000000', NULL, 1),
