(172117, 9399, 2480, '<td valign="top">How do you manage the effect?</td>', 'How do you manage the effect?', '2002-12-14 21:40:52.000000', NULL, 1),
(172118, 9533, 2480, '<td valign="top">You can almost feel you are in the moive!</td>', 'You can almost feel you are in the moive!', '2002-12-14 21:44:32.000000', NULL, 1),
