(172480, 9414, 1031, '<td valign="top">Beautiful exposure control in a tricky lighting situation.</td>', 'Beautiful exposure control in a tricky lighting situation.', '2002-12-15 15:39:38.000000', NULL, 1),
(172481, 9557, 4430, '<td valign="top">One of those dull gray days huh?  Did you try to brighten it any?  I like this pic though.</td>', 'One of those dull gray days huh?  Did you try to brighten it any?  I like this pic though.', '2002-12-15 15:41:18.000000', NULL, 1),
