(172548, 9404, 1031, '<td valign="top">Nice variety of colors in addition to all the action.</td>', 'Nice variety of colors in addition to all the action.', '2002-12-15 16:39:43.000000', NULL, 1),
(172549, 9280, 4596, '<td valign="top">Nice shot. Had the people in front been standing still too, it wouldn''t have worked. Very interesting given the near focus that you have on the merry-go-round. Seems almost like somebody ran in and out of the shot.</td>', 'Nice shot. Had the people in front been standing still too, it wouldn''t have worked. Very interesting given the near focus that you have on the merry-go-round. Seems almost like somebody ran in and out of the shot.', '2002-12-15 16:40:43.000000', NULL, 1),
(172550, 9322, 4596, '<td valign="top">Yup. Fits the bill.</td>', 'Yup. Fits the bill.', '2002-12-15 16:41:00.000000', NULL, 1),
(172551, 9563, 4596, '<td valign="top">It would have been better if not so grainy. Good effort. Nice hand motion.</td>', 'It would have been better if not so grainy. Good effort. Nice hand motion.', '2002-12-15 16:41:48.000000', NULL, 1),
(172552, 9518, 4596, '<td valign="top">Yes, well... fits the theme. But the shot isn''t anything too much here.</td>', 'Yes, well... fits the theme. But the shot isn''t anything too much here.', '2002-12-15 16:42:28.000000', NULL, 1),
(172553, 9306, 4596, '<td valign="top">Nice colours on this. The street light makes it. Seems like it may have been a wet night.</td>', 'Nice colours on this. The street light makes it. Seems like it may have been a wet night.', '2002-12-15 16:43:17.000000', NULL, 1),
