(172596, 9533, 1031, '<td valign="top">I''d maybe prefer a little softer frontlighting on the ship, but otherwise well-designed and executed; good use of panoramic crop.</td>', 'I''d maybe prefer a little softer frontlighting on the ship, but otherwise well-designed and executed; good use of panoramic crop.', '2002-12-15 17:21:54.000000', NULL, 1),
